pd.options.display.notebook_repr_html=False
def make_dir(directory, feature_change):
    cwd = f'{directory}/DRL_{feature_change}_plots'
    os.makedirs(cwd, exist_ok=True)
    return cwd
class PlotArgs():
    def __init__(self) -> None:
        self.cwd = None
        self.feature_change = None
        self.plot_on = None
def smooth(data, sm = 5):
        if sm > 1:
            smooth_data = []
            for n, d in enumerate(data):
                if n - sm + 1 >= 0:
                    y = np.mean(data[n - sm + 1: n])
                else:
                    y = np.mean(data[: n])
                smooth_data.append(y)
        return smooth_data

"""In this work, we focus on integrating a higher penetration of solar PV power into Great Britain's energy system for the years 2020, 2021, and 2022. We built several DL multivariate probabilistic and deterministic forecasting models to make a 24-hour ahead forecast with a 95% Prediction Interval and point forecasts of solar-PV power. Then, we model the energy system using the PyPSA tool and its Model-based Mixed Integer Non-Linear Programming (MINLP) to optimize it under the uncertainty of the 24-hour ahead probabilistic and point forecasts. We wanted to show if the average total cost of the energy system of the stochastically optimized capacities is lower or higher than the solutions from the deterministically determined capacities. The research questions include:
How much difference it really makes to the quality of the decisions reached if I use a stochastic problem instead of a deterministic problem? - ECIU METRIC
How much the expected costs could be reduced if system planner in the first stage knew exactly which scenario would happen? - EVPI METRIC

#**GluonTS - Probabilistic Time Series Modeling in Python**
"""

