"""#**Power/Energy System Optimization Using PyPSA Power System Analysis Tool**

**PyPSA can calculate: Energy system least-cost investment optimisation using linear network equations, over several snapshots simultaneously for optimisation of generation and storage dispatch**

PyPSA leans heavily on **linopy**: Linear optimization with N-dimensional labeled variables.

linopy is an open-source python package that facilitates optimization with real world data. It builds a bridge between data analysis packages like xarray & pandas and problem solvers like cbc, gurobi. Linopy supports Linear, Integer, Mixed-Integer and Quadratic Programming while aiming to make linear programming in Python easy, highly-flexible and performant.

PyPSA use linopy for preparing optimisation problems and currently supports linear and mixed-integer linear optimization. The optimisation allows the use one of the free solvers HiGHS, GLPK and CLP/CBC or commercial solvers like Gurobi or CPLEX.

**Why PyPSA?**

PyPSA is not as fully featured as other power system simulation tools such as the Matlab-based free software PSAT or the commercial package DIgSILENT PowerFactory.

However for power flow and optimal power flow over several time snapshots with variable renewable energy sources and/or storage and/or mixed AC-DC systems, it offers the flexibility of Python and the transparency of free software.

**Important Classes, Methods and Functions To Use**

1. **Classes:** pypsa.Network, lopf,
2. **Methods:** madd, consistency_check, export_to_csv_folder, create_model, solve_model,
3. **Functions:** get_committable_i, get_extendable_i, get_non_extendable_i,

**In PyPSA:**

It is assumed that the load is inelastic and must be met in every snapshot (this will be relaxed in future versions).

The objective function is the total system cost for the snapshots optimised.

Each snapshot can be given a weighting to represent e.g. multiple hours.

This set-up can also be used for stochastic optimisation, if you interpret the weighting as a probability.

The components Generator, Link, Store and StorageUnit components have a capital cost and a marginal cost.

Additional pre-defined constraints can be added to the optimisation problem via GlobalConstraint components.

###**Optimization with Linopy**
"""

n = pypsa.examples.ac_dc_meshed(from_master=True)
n.generators.carrier

# Nominal Capacity of Generators
n.generators.groupby("carrier")["p_nom"].sum()

n.buses

n.generators

n.snapshots

# Commented out IPython magic to ensure Python compatibility.
# %matplotlib inline
plt.rc("figure", figsize=(8, 8))
n.generators_t.p_max_pu.plot.area(subplots=True)
plt.tight_layout()

# set gas generators to non-extendable
n.generators.loc[n.generators.carrier == "gas", "p_nom_extendable"] = False
# add ramp limits
n.generators.loc[n.generators.carrier == "gas", "ramp_limit_down"] = 0.2
n.generators.loc[n.generators.carrier == "gas", "ramp_limit_up"] = 0.2
# add additional storage units (cyclic and non-cyclic) and fix one state_of_charge
n.add(
    "StorageUnit",
    "su",
    bus="Manchester",
    marginal_cost=10,
    inflow=50,
    p_nom_extendable=True,
    capital_cost=10,
    p_nom=2000,
    efficiency_dispatch=0.5,
    cyclic_state_of_charge=True,
    state_of_charge_initial=1000,
)
n.add(
    "StorageUnit",
    "su2",
    bus="Manchester",
    marginal_cost=10,
    p_nom_extendable=True,
    capital_cost=50,
    p_nom=2000,
    efficiency_dispatch=0.5,
    carrier="gas",
    cyclic_state_of_charge=False,
    state_of_charge_initial=1000,
)
n.storage_units_t.state_of_charge_set.loc[n.snapshots[7], "su"] = 100
# add an additional store.
n.add("Bus", "storebus", carrier="hydro", x=-5, y=55)
n.madd(
    "Link",
    ["battery_power", "battery_discharge"],
    "",
    bus0=["Manchester", "storebus"],
    bus1=["storebus", "Manchester"],
    p_nom=100,
    efficiency=0.9,
    p_nom_extendable=True,
    p_nom_max=1000,
)
n.madd(
    "Store",
    ["store"],
    bus="storebus",
    e_nom=2000,
    e_nom_extendable=True,
    marginal_cost=10,
    capital_cost=10,
    e_nom_max=5000,
    e_initial=100,
    e_cyclic=True,
)

# Storage Units Capacity
n.storage_units.groupby("carrier")["p_nom"].sum()

# run the ordinary linearized optimal power flow (LOPF)
n.optimize()

# Obtain the Real System Cost
print(f' The Objective is: {n.objective}')
print(f' The Real System Cost is: {n.objective + n.objective_constant}')

# modify the Model instance as much as you please, by directly adding or
# deleting variables or constraints etc.
n.model

## Modify model, optimize and feed back to network
# When you have a fresh network and you just want to create the model
# instance, run:
n.optimize.create_model()

## Through the model instance we gain a lot of flexibility.
# Let’s say for example we want to remove the Kirchhoff Voltage Law constraint,
# thus convert the model to a transport model. This can be done via:
n.model.constraints.remove("Kirchhoff-Voltage-Law")
# optimize the altered model and feed to solution back to the network
n.optimize.solve_model()

# Obtain the Real System Cost
print(f' The Objective is: {n.objective}')
print(f' The Real System Cost is: {n.objective + n.objective_constant}')

# Additional constraints
m = n.optimize.create_model()
# set a minimum state of charge of 50 MWh in our storage unit
sus = m.variables["StorageUnit-state_of_charge"]
m.add_constraints(sus >= 50, name="StorageUnit-minimum_soc")

# access the constraint and inspects its attributes
m.constraints["StorageUnit-minimum_soc"]

m.constraints["StorageUnit-minimum_soc"].sign

## Fix the ratio between ingoing and outgoing capacity of the Store
# The battery in our system is modelled with two links and a store. We should
# make sure that its charging and discharging capacities, meaning their links,
# are somehow coupled.
capacity = m.variables["Link-p_nom"]
eff = n.links.at["battery_power", "efficiency"]
lhs = capacity.loc["battery_power"] - eff * capacity.loc["battery_discharge"]
m.add_constraints(lhs == 0, name="Link-battery_fix_ratio")

# Every bus must in total produce the 20% of the total demand
total_demand = n.loads_t.p_set.sum().sum()
buses = n.generators.bus.to_xarray()
prod_per_bus = m.variables["Generator-p"].groupby(buses).sum().sum("snapshot")
m.add_constraints(prod_per_bus >= total_demand / 5, name="Bus-minimum_production_share")

# solve the network again
n.optimize.solve_model()

# Obtain the Real System Cost
print(f' The Objective is: {n.objective}')
print(f' The Real System Cost is: {n.objective + n.objective_constant}')

## Analysing the constraints
# Let’s see if the system got our own constraints.
n.model.constraints

n.links.loc[["battery_power", "battery_discharge"], ["p_nom_opt"]]

n.storage_units_t.state_of_charge

n.generators_t.p.groupby(n.generators.bus, axis=1).sum().sum() / n.loads_t.p.sum().sum()

"""Visualize optimal capacities for the generators"""

n.generators.p_nom_opt.div(1e3).plot.bar(ylabel="GW", figsize=(8, 3))
plt.tight_layout()

n.generators_t.p.div(1e3).plot.area(subplots=True, ylabel="GW")
plt.tight_layout()

# Visualize the Marginal Prices in the network
n.buses_t.marginal_price.mean(1).plot.area(figsize=(8, 3), ylabel="Euro per MWh")
plt.tight_layout()

# Visualize the active power injection per bus
n.buses_t.p

p_by_carrier = n.generators_t.p.groupby(n.generators.carrier, axis=1).sum()
p_by_carrier.columns

colors = {
    "wind": "blue",
    "gas": "orange",
}
