"""###**Energy-only Electricity Market With Variable Renewables and Storage**

**Scenario: Single bidding zone with fixed load and storage, several periods**

We consider multiple time periods to represent **variable wind generation**. Storage is allowed to do price arbitrage to reduce oil consumption.

**Define the Data**
"""

# marginal costs in EUR/MWh
marginal_costs = {"Wind": 0, "Hydro": 0, "Coal": 30, "Gas": 60, "Oil": 80}
# power plant capacities (nominal powers in MW)
power_plant_p_nom = {
    "Great Britain": {"Coal": 35000, "Wind": 3000, "Gas": 8000, "Oil": 2000},
}
# country electrical loads in MW
loads = {"Great Britain": 42000}

country = "Great Britain"
network = pypsa.Network()
# snapshots
network.set_snapshots(range(4))
network.add("Bus", country)

# p_max_pu is variable for wind
for tech in power_plant_p_nom[country]:
    network.add(
        "Generator",
        "{} {}".format(country, tech),
        bus=country,
        p_nom=power_plant_p_nom[country][tech],
        marginal_cost=marginal_costs[tech],
        p_max_pu=([0.3, 0.6, 0.4, 0.5] if tech == "Wind" else 1),
    )

# load which varies over the snapshots
network.add(
    "Load",
    "{} load".format(country),
    bus=country,
    p_set=loads[country] + np.array([0, 1000, 3000, 4000]),
)

# storage unit to do price arbitrage
network.add(
    "StorageUnit",
    "{} pumped hydro".format(country),
    bus=country,
    p_nom=1000,
    max_hours=6,  # energy storage in terms of hours at full power
)

network.generators.carrier

