"""#**Stochastic Optimisation**

#**A Great Britain's Case Study**

**Highlights:**

PyPSA can optimise the dispatch of generation and storage and the capacities of generation, storage and transmission infrastructure.

The objective function is the total system cost for the snapshots optimised.

**In this study, we optimise a single node (Great Britain) with only a Wind, Solar, Gas, Hydro, Nuclear, Biomass, Coal, Imports, stoarge, and Other generators under uncertainty about the Solar-PV Power and gas Price.**

In Stage 1 decisions are made about capacities of the generators under the variability of solar-PV Power while the system gas is unknown.

First we solve with the knowledge about the gas price, then stochastically according to the probability distribution of the gas price.

**The Question**

How much difference it really makes to the quality of the decisions reached if I use a stochastic problem instead of a deterministic problem? - ECIU METRIC

How much the expected costs could be reduced if system planner in the first stage knew exactly which scenario would happen? - EVPI METRIC

**Focus:**

The cost of **making investment decision** **considering uncertainty**

The cost of **making investment decision** **Ignoring uncertainty**

**In this study, we focus on the cost accrued while making investment decisions considering or ignoring uncertainty.**

##**Data Collection**

By **National Grid Electricity System Operator - ESO**

The ESO is the electricity system operator for Great Britain.

**Historic Generation Mix & Carbon Intensity:**

This dataset contains data from the 1st of Jan 2009. It has seasonal decomposition applied to correct missing or irregular data points. The carbon intensity of electricity is a measure of how much Carbon dioxide emissions are produced per kilowatt hour of electricity consumed.

**Historic Demand Data:**

This section contains historic electricity demand, interconnector, hydro storage pumping, Non-BM Short Term Operating Reserve (STOR), wind and solar outturn data.

**Elexon BMRS System Electricity Price.**

###**Download the Datasets**

Download the systemSellPrice and	systemBuyPrice by Scraping the Elexon API, Upload other datasets, and Resample to Hourly timesteps.
"""

