df_All_2022 = pd.read_csv('/content/gdrive/MyDrive/Energy_System_RL_Modeling_Data/ESO_Historic_Generation_Mix_GB_Demand_System_Prices_2022.csv')

df_All_2020['DATETIME'] = pd.to_datetime(df_All_2020['DATETIME'])
df_All_2020.set_index('DATETIME', inplace=True)
df_All_2020['systemSellPrice'].fillna(method='ffill', inplace=True)
df_All_2020['systemSellPrice'].fillna(method='bfill', inplace=True)
df_All_2020['systemBuyPrice'].fillna(method='ffill', inplace=True)
df_All_2020['systemBuyPrice'].fillna(method='bfill', inplace=True)
df_All_2020_hourly = df_All_2020.resample('H').mean()
df_All_2020_hourly.reset_index(inplace=True)

df_All_2021['DATETIME'] = pd.to_datetime(df_All_2021['DATETIME'])
df_All_2021.set_index('DATETIME', inplace=True)
df_All_2021['systemSellPrice'].fillna(method='ffill', inplace=True)
df_All_2021['systemSellPrice'].fillna(method='bfill', inplace=True)
df_All_2021['systemBuyPrice'].fillna(method='ffill', inplace=True)
df_All_2021['systemBuyPrice'].fillna(method='bfill', inplace=True)
df_All_2021_hourly = df_All_2021.resample('H').mean()
df_All_2021_hourly.reset_index(inplace=True)

df_All_2022['DATETIME'] = pd.to_datetime(df_All_2022['DATETIME'])
df_All_2022.set_index('DATETIME', inplace=True)
df_All_2022['systemSellPrice'].fillna(method='ffill', inplace=True)
df_All_2022['systemSellPrice'].fillna(method='bfill', inplace=True)
df_All_2022['systemBuyPrice'].fillna(method='ffill', inplace=True)
df_All_2022['systemBuyPrice'].fillna(method='bfill', inplace=True)
