"""**Using the powerplantmatching tool to obtain further information (Metadata)about the Power Plants in Great Britain**

powerplantmatching is a toolset for cleaning, standardizing and combining multiple power plant databases.

Obtain the Conventional Power Plant Efficiencies

Renewable Plants are taken as 1
"""

import powerplantmatching as pm
config = pm.get_config()
config_UK2023 = copy.copy(config)
config_UK2023["main_query"] = "Country == 'United Kingdom'"
config_UK2023["hash"] = "UK-2023"

for config in [config_UK2023]:
    label = config["hash"]
    df = pm.powerplants(config=config, update=True)
    df = df[df.lat.notnull()]
    grouped = (
        df.groupby(["Fueltype", "Country"])
        .Capacity.sum()
        .div(1e3)
        .sort_index(level=1, ascending=False)
    )
    df_coal = df[df['Fueltype'] == 'Hard Coal']
