"""Using the 2019 BEIS long-term assumptions for the wholesale prices of gas for the UK.

**BEIS** - The Department for Business, Energy, Industrial, and Strategy.

These assumptions are required for long-term modelling of the UK energy system and economic appraisal.

They are not forecasts of future energy prices. To capture these uncertainties, analysts should use the High and Low assumptions for sensitivity analysis rather than just using the Central assumptions.

High and Low gas price assumptions are derived as a range around the Central price assumptions using data on NBP options volatility. A confidence level of 75% is selected i.e. suggesting that the market attached a 75% likelihood that the gas price will fall within High-Low price range.

The Gas price is the GB National Balancing Point (NBP) spot price, which is quoted in pence/therm.
"""

df_gas_price = pd.read_csv('/content/gdrive/MyDrive/Energy_System_RL_Modeling_Data/BEIS_Gas_Price_Assumptions.csv')

"""**Gas Price Assumption**"""

print(df_gas_price.to_markdown())

"""**Using the BEIS Electricity Generation Costs (2016 and 2020) - Technical and Cost Assumptions for Generation Technologies**

Data for Nuclear, Coal, and Pump Hydro Storage are obtained from 2016 BEIS Electricity Generation Cost Assumptions, while other generation technologies are obtained from 2020 publication.

Assuming Projects Commissioning in 2025, and 2018 prices

3.5% Discount Rate

The 'MEDIUM' Scenario is used

Wind is modelled as 85% onshore and 15% offshore, while solar is modeled as large scale.

The levelised cost estimates of electricity generation **(LCOE)** is taken as the Marginal cost of generation since  A ‘levelised cost’ is the average cost over the lifetime of the plant per MWh of electricity generated.

 The Levelised Cost of Electricity Generation is the discounted lifetime cost of ownership and use of a generation asset, converted into an equivalent unit of cost of generation in £/MWh.

 It is calculated using the BEIS Levelised Cost Model.

 **Marginal Cost** is the Marginal cost of production of 1 MWh (£/MWh).

 **Capex Costs** is the sum of Pre-development, Construction, & Infrastructure costs


 BEIS does not give the Infrastructure cost for Hydro Power. We assumed this to be 500 kW	@ £1.6M as given in:
 https://renewablesfirst.co.uk/renewable-energy-technologies/hydropower/hydropower-learning-centre/how-much-do-hydropower-systems-cost-to-build/

 We model **Pump Hydro Storage** as a Generation Technology
"""

df_electricity_gen_cost_2020 = pd.read_csv(
    '/content/gdrive/MyDrive/Energy_System_RL_Modeling_Data/Key_data_and_Assumptions_for_generation_technologies.csv',
    encoding='latin-1')
df_electricity_gen_cost_2020

