"""**Obtain the Capital Cost (CAPEX) for all Generators - 2022**"""

print('============================================')
gas_capex = (df_All_2022_hourly.GAS.max()/1200) * float(df_electricity_gen_cost_2020.loc[df_electricity_gen_cost_2020['Technology'] == 'Capital Cost', 'CCGT H Class'].values[0])
print('GAS CAPEX IS: {:.2f} £/MW'.format(gas_capex))
print('============================================')
coal_capex = (df_All_2022_hourly.COAL.max()/760) * float(df_electricity_gen_cost_2020.loc[df_electricity_gen_cost_2020['Technology'] == 'Capital Cost', 'Coal - CCS  IGCC partial FOAK'].values[0])
print('COAL CAPEX IS: {:.2f} £/MW'.format(coal_capex))
print('============================================')
nuclear_capex = (df_All_2022_hourly.NUCLEAR.max()/3300) * float(df_electricity_gen_cost_2020.loc[df_electricity_gen_cost_2020['Technology'] == 'Capital Cost', 'Nuclear - PWR FOAK'].values[0])
print('NUCLEAR CAPEX IS: {:.2f} £/MW'.format(nuclear_capex))
print('============================================')
wind_capex_onshore = (df_All_2022_hourly.WIND.max()/51) * float(df_electricity_gen_cost_2020.loc[df_electricity_gen_cost_2020['Technology'] == 'Capital Cost', 'Onshore Wind'].values[0])
wind_capex_offshore = (df_All_2022_hourly.WIND.max()/1000) * float(df_electricity_gen_cost_2020.loc[df_electricity_gen_cost_2020['Technology'] == 'Capital Cost', 'Offshore Wind'].values[0])
wind_capex = 0.85 * wind_capex_onshore + 0.15 * wind_capex_offshore
print('WIND CAPEX IS: {:.2f} £/MW'.format(wind_capex))
print('============================================')
hydro_capex = (df_All_2022_hourly.HYDRO.max()/11) * float(df_electricity_gen_cost_2020.loc[df_electricity_gen_cost_2020['Technology'] == 'Capital Cost', 'Hydro 5-16MW'].values[0])
print('HYDRO CAPEX IS: {:.2f} £/MW'.format(hydro_capex))
print('============================================')
imports_capex = (df_All_2022_hourly.IMPORTS.max()/1200) * float(df_electricity_gen_cost_2020.loc[df_electricity_gen_cost_2020['Technology'] == 'Capital Cost', 'CCGT H Class'].values[0]) # We assumed Imports to be a gas plant source
print('IMPORTS CAPEX IS: {:.2f} £/MW'.format(imports_capex))
print('============================================')
biomass_capex = (df_All_2022_hourly.BIOMASS.max()/23) * float(df_electricity_gen_cost_2020.loc[df_electricity_gen_cost_2020['Technology'] == 'Capital Cost', 'Dedicated Biomass'].values[0])
print('BIOMASS CAPEX IS: {:.2f} £/MW'.format(biomass_capex))
