solar_capex = (df_All_2022_hourly.SOLAR.max()/16) * float(df_electricity_gen_cost_2020.loc[df_electricity_gen_cost_2020['Technology'] == 'Capital Cost', 'Large-scale Solar'].values[0])
print('SOLAR CAPEX IS: {:.2f} £/MW'.format(solar_capex))
