"""**Calculate Gas Price Confidence Levels and use as Probability Distribution**"""

gas_price_assumptions = {
    'central': 50,  # Central gas price assumption
    'high': 75,     # High gas price assumption
    'low': 33       # Low gas price assumption
}
confidence_level = 0.75  # 75% confidence level
# Calculate the range around the central price based on the confidence level
price_range = (gas_price_assumptions['high'] - gas_price_assumptions['low']) * confidence_level
# Calculate the high and low bounds for the gas price
high_bound = gas_price_assumptions['central'] + (price_range / 2)
low_bound = gas_price_assumptions['central'] - (price_range / 2)
# Create a dictionary to represent the statement
gas_price_statement = {
    'central': gas_price_assumptions['central'],
    'high': gas_price_assumptions['high'],
    'low': gas_price_assumptions['low'],
    'confidence_level': confidence_level,
    'high_bound': high_bound,
    'low_bound': low_bound
}
print(gas_price_statement)

"""**Major settings - 2022**"""

scenarios = ["low", "med", "high"]
# this just determines the default scenario when building stochastic model
base_scenario = "low"
# For Year 2022 in pence/therm
gas_prices = {"low": 33, "med": 50, "high": 75}
probability = {"low": 0.34, "med": 0.75, "high": 0.66} # Probability Distribution
year_start = 2022 #2021, 2020
year_end = 2022 #2021, 2020
# 1 is hourly
frequency = 1
solver_name = "highs"
cts = ["GB"]

