"""**Required functions**

Create the base network - Energy Only With Pumped Hydro Storage UK (**without stochastic optimisation**)
"""

df_All_2022 = pd.read_csv('/content/gdrive/MyDrive/Energy_System_RL_Modeling_Data/ESO_Historic_Generation_Mix_GB_Demand_System_Prices_2022.csv',
                          parse_dates=["DATETIME"], index_col="DATETIME")
df_All_2022_hourly = df_All_2022.resample('H').mean()
df_All_2022_hourly.fillna(method='bfill', inplace=True)
df_All_2022_hourly.fillna(method='ffill', inplace=True)
# Solar Availability
solar_pu = df_All_2022_hourly['SOLAR']['2022-01-01 00:00:00':'2022-01-01 23:00:00'].values / df_All_2022_hourly.SOLAR.max()
#wind_pu = df_All_2022_hourly['WIND'].values
load = df_All_2022_hourly['ND']['2022-01-01 00:00:00':'2022-01-01 23:00:00'].values.tolist()
efficiency = df_electricity_gen_cost_2020.loc[df_electricity_gen_cost_2020['Technology'] == 'Average fuel efficiency', 'CCGT H Class'].iloc[0]
country = "Great Britain"

def prepare_network(gas_price):
    network = pypsa.Network()
    snapshots = pd.date_range(
        "{}-01-01".format(year_start),
        "{}-01-01 23:00".format(year_end),
        freq=str(frequency) + "H",
    )
    network.set_snapshots(snapshots)
    network.snapshot_weightings = pd.Series(float(frequency),
                                            index=network.snapshots)
    # Add the Bus
    network.add("Bus", country, y=55.378, x=3.436)
    # Add Load Demand in MW which varies over the snapshots
    network.add("Load", "{} load".format(country), bus = country,
                p_set = [22183.5, 21294.5, 19095.0, 17811.5, 16879.5, 16487.5, 17110.0, 17892.5, 18947.5, 20355.5, 21809.5, 23441.5, 24753.0, 25363.0, 25572.0, 26815.0, 29542.0, 31032.0, 29972.0, 28409.0, 26629.5, 25073.0, 22788.0, 20835.0])
    # Add the Generators
    network.add(
        "Generator",
        #ct + " solar",
        "{}".format(country) + " solar",
        bus = country,
        p_max_pu = solar_pu,
        p_nom = df_All_2022_hourly.SOLAR.max(),
        p_nom_extendable = True,
        lifetime = df_electricity_gen_cost_2020.loc[df_electricity_gen_cost_2020['Technology'] == 'Operating lifetime', 'Large-scale Solar'].values[0],
        build_year = 2025,
        marginal_cost = solar_LCOE_Marginal_Cost,
        capital_cost = solar_capex,
        )
    network.add(
        "Generator",
        #ct + " wind",
        "{}".format(country) + " wind",
        bus = country,
        p_max_pu = 1,
        p_nom = df_All_2022_hourly.WIND.max(),
        p_nom_extendable = True,
        lifetime = df_electricity_gen_cost_2020.loc[df_electricity_gen_cost_2020['Technology'] == 'Operating lifetime', 'Onshore Wind'].values[0],
        build_year = 2025,
        marginal_cost = wind_LCOE_Marginal_Cost,
        capital_cost = wind_capex,
        )
    network.add(
        "Generator",
        #ct + " gas",
        "{}".format(country) + " gas",
        bus = country,
        p_max_pu = 1,
        p_nom = df_All_2022_hourly.GAS.max(),
        p_nom_extendable = True,
        lifetime = df_electricity_gen_cost_2020.loc[df_electricity_gen_cost_2020['Technology'] == 'Operating lifetime', 'CCGT H Class'].values[0],
        build_year = 2025,
        efficiency = df_electricity_gen_cost_2020.loc[df_electricity_gen_cost_2020['Technology'] == 'Average fuel efficiency', 'CCGT H Class'].values[0],
        marginal_cost = gas_price / float(efficiency),
        capital_cost = gas_capex,
        )
    network.add(
        "Generator",
        #ct + " coal",
        "{}".format(country) + " coal",
        bus = country,
        p_max_pu = 1,
        # Add ramp limits
        # We set this speed limit 25% for coal plants.
        ramp_limit_up = 0.25,
        ramp_limit_down = 0.25,
        p_nom = df_All_2022_hourly.COAL.max(),
        p_nom_extendable = True,
        lifetime = df_electricity_gen_cost_2020.loc[df_electricity_gen_cost_2020['Technology'] == 'Operating lifetime', 'Coal - CCS  IGCC partial FOAK'].values[0],
        build_year = 2025,
        marginal_cost = coal_LCOE_Marginal_Cost,
        capital_cost = coal_capex,
        )
    network.add(
        "Generator",
        #ct + " nuclear",
        "{}".format(country) + " nuclear",
        bus = country,
        p_max_pu = 1,
        # Add ramp limits
        # We set this speed limit 20% for nuclear plants.
        ramp_limit_up = 0.2,
        ramp_limit_down = 0.2,
        p_nom = df_All_2022_hourly.NUCLEAR.max(),
        p_nom_extendable = True,
        lifetime = df_electricity_gen_cost_2020.loc[df_electricity_gen_cost_2020['Technology'] == 'Operating lifetime', 'Nuclear - PWR FOAK'].values[0],
        build_year = 2025,
        marginal_cost = nuclear_LCOE_Marginal_Cost,
        capital_cost = nuclear_capex,
        )
    network.add(
        "Generator",
        #ct + " hydro",
        "{}".format(country) + " hydro",
        bus = country,
        p_max_pu = 1,
        p_nom = df_All_2022_hourly.HYDRO.max(),
        p_nom_extendable = True,
        lifetime = df_electricity_gen_cost_2020.loc[df_electricity_gen_cost_2020['Technology'] == 'Operating lifetime', 'Hydro 5-16MW'].values[0],
        build_year = 2025,
        marginal_cost = hydro_LCOE_Marginal_Cost,
        capital_cost = hydro_capex,
        )
    network.add(
        "Generator",
        #ct + " biomass",
        "{}".format(country) + " biomass",
        bus = country,
        p_max_pu = 1,
        p_nom = df_All_2022_hourly.BIOMASS.max(),
        p_nom_extendable = True,
        lifetime = df_electricity_gen_cost_2020.loc[df_electricity_gen_cost_2020['Technology'] == 'Operating lifetime', 'Dedicated Biomass'].values[0],
        build_year = 2025,
        marginal_cost = biomass_LCOE_Marginal_Cost,
        capital_cost = biomass_capex,
        )
    network.add(
        "Generator",
        #ct + " storage", # Modelled as Gas
        "{}".format(country) + " storage",
        bus = country,
        p_max_pu = 1,
        p_nom = df_All_2022_hourly.STORAGE.max(),
        p_nom_extendable = True,
        lifetime = df_electricity_gen_cost_2020.loc[df_electricity_gen_cost_2020['Technology'] == 'Operating lifetime', 'Pumped storage'].values[0],
        build_year = 2025,
        marginal_cost = storage_LCOE_Marginal_Cost,
        capital_cost = storage_capex,
        )
    network.add(
        "Generator",
        #ct + " imports", # Modelled as Gas
        "{}".format(country) + " imports",
        bus = country,
        p_max_pu = 1,
        p_nom = df_All_2022_hourly.IMPORTS.max(),
        p_nom_extendable = True,
        lifetime = df_electricity_gen_cost_2020.loc[df_electricity_gen_cost_2020['Technology'] == 'Operating lifetime', 'CCGT H Class'].values[0],
        build_year = 2025,
        marginal_cost = imports_LCOE_Marginal_Cost,
        capital_cost = imports_capex,
        )
    network.add(
        "Generator",
        #ct + " other", # Modelled as Gas
        "{}".format(country) + " other",
        bus = country,
        p_max_pu = 1,
        p_nom = df_All_2022_hourly.OTHER.max(),
        p_nom_extendable = True,
        lifetime = df_electricity_gen_cost_2020.loc[df_electricity_gen_cost_2020['Technology'] == 'Operating lifetime', 'CCGT H Class'].values[0],
        build_year = 2025,
        marginal_cost = other_LCOE_Marginal_Cost,
        capital_cost = other_capex,
        )
    # storage unit to do price arbitrage
    network.add(
        "StorageUnit",
        #ct + "Pumped Hydro",
        "{}".format(country) + " Pumped Hydro",
        bus = country,
        p_nom = 1000,
        p_nom_extendable = True,
        max_hours = 6,  # energy storage in terms of hours at full power
        )
    return network
    # All generators have a p_nom_extendable set to True, meaning that capacities
    # can be extended in the optimization.

