"""#**Day-ahead redispatch hybrid optimization of future solar-PV and wind power integrated 18-zone Great Britain energy system**

**A sensitivity analysis is also carried out against several factors to demonstrate the dynamic performance of the test system incorporating the built redispatch market model under renewable energies’ penetration levels of between 60 %, and 101 % of system demand.**

###**Using the Electricity System Operator (ESO) ETYS 2023 Future Energy System (FES) Data**

The Electricity Ten Year Statement (ETYS) outlines ESO of the National Electricity Transmission System (NETS) over the next ten to twenty years.

The ETYS is the Electricity System Operator’s (ESO) view of future transmission requirements, and the capability of Great Britain’s National Electricity
Transmission System (NETS) based on their latest Future Energy Scenarios (FES). The ETYS 2023 enables them to understand what investment and development is required to maintain a safe and reliable operational network, while enabling us to achieve our zero-carbon ambition.

The analysis this year continues to show growing system needs driven primarily by low carbon and renewable generation. This will drive requirements for new network capability as we continue to move towards the **2035 government target of 100% zero carbon electricity system** and beyond.

The ETYS is important in helping to understand where investment and development is needed to help achieve the zero-carbon ambition. The ETYS 2023 key messages explain the key system need insights from the analysis of the latest Future Energy Scenarios.

The NETS is otherwise known as the Electricity Transmission network which spans across Great Britain. The network comprises a mixture of overhead cables,underground cabling and subsea cables – the size of these assets varies from of 400kV, 275kV and 132kV assets. These are all linked together via substations across the country that then connect separately owned generators,interconnectors, large demands, and distribution systems.

To identify the future transmission requirements of the GB NETS there are several inputs that are fed into the planning process and at various stages. Amongst whom is the FES Data used to Determine Demand and Generation.

**FES** are a credible range of scenarios for how energy will be produced and
consumed up to 2050. These scenarios form the foundation of the studies and analysis, and they are used to determine the peak demand and generation capacity regionally.

**Reducing the GB NETS to an Equivalent Energy Only 18-BUS Network:**

A 18-bus equivalent network representing the National Electricity Transmission System of Great Britain is created using the ETYS Data. The entire system is split into 18 Flop zones for which the relevant generation and demand were evaluated. Generators within each zone were categorised into fuel types and the demand was split into active demand.
The approach adopted to create this model is to initially segregate the transmission network into 18 different Major flop zones. Each zone is represented by a substation to which the relevant generators and loads are connected and thus all generators in the zone are represented by an equivalent generator regardless of the electrical distance between them.
"""

df_regional_eso_fes_2025 = pd.read_csv('/content/gdrive/MyDrive/Energy_System_RL_Modeling_Data/Regional breakdown of ESO FES data - 2025 - FLOP-ZONES.csv',
                                       encoding='latin-1')
