"""###**Recalibrate The Model's Predictive Uncertainties, Evaluate It, and Create Calibration Plots**"""

# Create a subplot grid of 3 rows and 5 columns
fig, axes = plt.subplots(3, 5, figsize=(25, 25))
fig.set_facecolor("white")
axes = axes.ravel()
# Define empty lists to accumulate metrics values
agg_mae = []
agg_rmse = []
agg_mdae = []
agg_marpd = []
agg_r2 = []
agg_corr = []
agg_rms_cal = []
agg_ma_cal = []
agg_miscal_area = []
agg_sharp = []
agg_nll = []
agg_crps = []
agg_check = []
agg_interval = []
# Define a function to perform the calculations for a given station
def compute_metrics_for_station(station_name, station_num, ax):
    # Extract the predicted and target_test data for the current station
    num_samples = 100
    samples_mean = forecasts[station_num].samples
    samples_var = np.var(samples_mean, axis=0)
    samples_mean_recal = forecasts_recal[station_num].samples
    mean = np.mean(samples_mean_recal, axis=0)
    samples_var_recal = np.var(samples_mean_recal, axis=0)
    mixture_mean = torch.mean(torch.tensor(samples_mean), dim=0)
    mixture_mean_recal = torch.mean(torch.tensor(samples_mean_recal), dim=0)
    aleatoric = torch.tensor(samples_var)
    aleatoric_recal = torch.tensor(samples_var_recal)
    epistemic = torch.sum(torch.square(torch.tensor(samples_mean) - mixture_mean), dim=0) / (num_samples - 1)
    total_unc = aleatoric + epistemic
    std = torch.sqrt(total_unc)
    epistemic_recal = torch.sum(torch.square(torch.tensor(samples_mean_recal) - mixture_mean_recal), dim=0) / (num_samples - 1)
    total_unc_recal = aleatoric_recal + epistemic_recal
    std_recal = torch.sqrt(total_unc_recal)
    target_test = tss[station_num][-24 :]
    target_test_recal = tss_recal[station_num][-24 :]
    """Recalibrate predictive uncertainties"""
    try:
        exp_props, obs_props = uct.metrics_calibration.get_proportion_lists_vectorized(
            mixture_mean_recal.numpy(), std_recal.numpy(), target_test_recal.values.reshape(-1))
    except AssertionError:
        std_recal = np.maximum(std_recal, 1e-6)
        exp_props, obs_props = uct.metrics_calibration.get_proportion_lists_vectorized(
            mixture_mean_recal.numpy(), std_recal.numpy(), target_test_recal.values.reshape(-1))
    # Train a recalibration model.
    recal_model = uct.recalibration.iso_recal(exp_props, obs_props)
    # Get the expected props and observed props using the new recalibrated model
    try:
        te_recal_exp_props, te_recal_obs_props = uct.metrics_calibration.get_proportion_lists_vectorized(
            mixture_mean.numpy(), std.numpy(), target_test.values.reshape(-1), recal_model=recal_model)
    except AssertionError:
        std = np.maximum(std, 1e-6)
        te_recal_exp_props, te_recal_obs_props = uct.metrics_calibration.get_proportion_lists_vectorized(
            mixture_mean.numpy(), std.numpy(), target_test.values.reshape(-1), recal_model=recal_model)
    """Recalibrate by finding scaling to standard deviation output."""
    std_scaling = uct.recalibration.optimize_recalibration_ratio(
          mixture_mean_recal.numpy(), std_recal.numpy(), target_test_recal.values.reshape(-1), criterion="miscal")
    new_pred_stds = std_scaling * std
    new_pred_var = np.square(new_pred_stds)
    # Obtain Aleatoric and Epistemic Uncertainty
    new_pred_var = torch.tensor(new_pred_var)
    samples_mean = torch.tensor(samples_mean)
    mixture_mean = torch.tensor(mixture_mean)
    samples_var = torch.tensor(samples_var)
    aleatoric = new_pred_var
    total_recal_uncertainty = aleatoric + epistemic
    # Plot average calibration in a subplot
    uct.viz.plot_calibration(mixture_mean.numpy(), new_pred_stds.numpy(), target_test.values.reshape(-1), ax=ax)
    ax.set_title(f"{station_name}", size=18, fontweight='bold')
    ax.set_ylabel('Observed Proportion in Interval', size=18, fontweight='bold')
    ax.tick_params(axis='x', rotation=0, labelsize=15)
    ax.xaxis.label.set_fontweight('bold')
    ax.tick_params(axis='y', rotation=0, labelsize=15)
    ax.yaxis.label.set_fontweight('bold')
    ax.legend(loc="upper left", ncol=1, frameon=True, fontsize='10',
              fancybox=True, framealpha=1, shadow=True, borderpad=1)
    ax.xaxis.grid(False)  # Remove x-axis grid lines
    ax.yaxis.grid(False)
    for spine in ax.spines.values():
        spine.set_linewidth(2)
        spine.set_edgecolor('black')
    # Get all metrics
    metrics = uct.metrics.get_all_metrics(mixture_mean.numpy(), new_pred_stds.numpy(), target_test.values.reshape(-1))
    # Print metrics for the current station
    print(f"======================Metrics for Station: {station_name}=================================")
    print("Accuracy Metrics:", metrics['accuracy'])
    print('===============================================================================================')
    print("Average Calibration Metrics:", metrics['avg_calibration'])
    print('===============================================================================================')
    print("Sharpness Metrics:", metrics['sharpness'])
    print('===============================================================================================')
    print("Scoring Rule Metrics:", metrics['scoring_rule'])
    print('===============================================================================================')
    print("Aleatoric Uncertainty:", aleatoric)
    print('===============================================================================================')
    print("Epistemic Uncertainty:", epistemic)
    print('===============================================================================================')
    print("Total Uncertainty:", total_recal_uncertainty)
    print('===============================================================================================')
    # Extract specific metrics values
    mae = metrics['accuracy']['mae']
    rmse = metrics['accuracy']['rmse']
    mdae = metrics['accuracy']['mdae']
    marpd = metrics['accuracy']['marpd']
    r2 = metrics['accuracy']['r2']
    corr = metrics['accuracy']['corr']
    rms_cal = metrics['avg_calibration']['rms_cal']
    ma_cal = metrics['avg_calibration']['ma_cal']
    miscal_area = metrics['avg_calibration']['miscal_area']
    sharp = metrics['sharpness']['sharp']
    nll = metrics['scoring_rule']['nll']
    crps = metrics['scoring_rule']['crps']
    check = metrics['scoring_rule']['check']
    interval = metrics['scoring_rule']['interval']
    # Append metrics values to the corresponding lists
    agg_mae.append(mae)
    agg_rmse.append(rmse)
    agg_mdae.append(mdae)
    agg_marpd.append(marpd)
    agg_r2.append(r2)
    agg_corr.append(corr)
    agg_rms_cal.append(rms_cal)
    agg_ma_cal.append(ma_cal)
    agg_miscal_area.append(miscal_area)
    agg_sharp.append(sharp)
    agg_nll.append(nll)
    agg_crps.append(crps)
    agg_check.append(check)
    agg_interval.append(interval)
    print("=" * 100)
# Define the names of the 15 stations
station_names = [
    "Arlington Solar PV", "Bowler Solar PV", "Weston Solar PV", "Walker Generating Co Solar PV ", "Dundonald Solar PV",
    "Maxwood Solar PV", "CBS Teversham Solar PV", "Myrtle Avenue Solar PV", "The Cats Slide Solar PV",
    "Gillingham Generator Solar PV", "PaulsPV Solar PV", "Porth Solar PV", "Casa Cousins Solar PV",
    "Mawnan Castle Solar PV", "Rose Sycamore Solar PV"]
# Define the number of stations
num_stations = len(station_names)
# Loop through each station and compute metrics
for station_name, station_num, ax in zip(station_names, range(num_stations), axes):
    compute_metrics_for_station(station_name, station_num, ax)
    # Set the aspect ratio of each subplot axis to be equal
    ax.set_aspect('auto')
# Calculate the average of each metric
avg_mae = np.mean(agg_mae)
avg_rmse = np.mean(agg_rmse)
avg_mdae = np.mean(agg_mdae)
avg_marpd = np.mean(agg_marpd)
avg_r2 = np.mean(agg_r2)
avg_corr = np.mean(agg_corr)
avg_rms_cal = np.mean(agg_rms_cal)
avg_ma_cal = np.mean(agg_ma_cal)
avg_miscal_area = np.mean(agg_miscal_area)
avg_sharp = np.mean(agg_sharp)
avg_nll = np.mean(agg_nll)
avg_crps = np.mean(agg_crps)
avg_check = np.mean(agg_check)
avg_interval = np.mean(agg_interval)
# Print the average metrics values
print(f"=================Aggregate Metrics for All Stations:=================================")
print("Average MAE:", avg_mae)
print("Average RMSE:", avg_rmse)
print("Average MDAE:", avg_mdae)
print("Average MARPD:", avg_marpd)
print("Average R2:", avg_r2)
