axes = axes.ravel()
test_start = '2020-12-31 00:00:00'
test_end = '2020-12-31 23:00:00'
test_index = pd.date_range(start=test_start, end=test_end, freq='H')
# Define a function to perform the calculations for a given station
def create_plots_for_station(station_name, station_num, ax):
    # Extract the predicted and target_test data for the current station
    num_samples = 100
    target_test = tss[station_num][-24 :]
    target_test_recal = tss_recal[station_num][-24 :]
    samples_mean = forecasts[station_num].quantile(0.5)
    samples_mean_recal = forecasts_recal[station_num].quantile(0.5)
    mixture_mean = torch.tensor(samples_mean)
    mixture_mean_recal = torch.tensor(samples_mean_recal)
    residual = target_test.values.reshape(-1) - samples_mean
    aleatoric = np.std(residual)
    aleatoric = np.full_like(residual, aleatoric)
    residual_recal = target_test_recal.values.reshape(-1) - samples_mean_recal
    aleatoric_recal = np.std(residual_recal)
    aleatoric_recal = np.full_like(residual_recal, aleatoric_recal)
    epistemic = forecasts[station_num].quantile(0.9) - forecasts[station_num].quantile(0.1)
    total_unc = aleatoric + epistemic
    std = torch.sqrt(torch.tensor(total_unc))
    epistemic_recal = forecasts_recal[station_num].quantile(0.9) - forecasts_recal[station_num].quantile(0.1)
    total_unc_recal = aleatoric_recal + epistemic_recal
    std_recal = torch.sqrt(torch.tensor(total_unc_recal))
    """Recalibrate predictive uncertainties"""
    exp_props, obs_props = uct.metrics_calibration.get_proportion_lists_vectorized(
        mixture_mean_recal.numpy(), std_recal.numpy(), target_test_recal.values.reshape(-1))
    # Train a recalibration model.
    recal_model = uct.recalibration.iso_recal(exp_props, obs_props)
    # Get the expected props and observed props using the new recalibrated model
    te_recal_exp_props, te_recal_obs_props = uct.metrics_calibration.get_proportion_lists_vectorized(
        mixture_mean.numpy(), std.numpy(), target_test.values.reshape(-1), recal_model=recal_model)
    """Recalibrate by finding scaling to standard deviation output."""
    std_scaling = uct.recalibration.optimize_recalibration_ratio(
          mixture_mean_recal.numpy(), std_recal.numpy(), target_test_recal.values.reshape(-1), criterion="miscal")
    new_pred_stds = std_scaling * std
    new_pred_var = np.square(new_pred_stds)
    # Obtain Aleatoric and Epistemic Uncertainty
    new_pred_var = torch.tensor(new_pred_var)
    samples_mean = torch.tensor(samples_mean)
    mixture_mean = torch.tensor(mixture_mean)
    aleatoric = new_pred_var
    total_recal_uncertainty = aleatoric + epistemic
    Standard_scores = {'z_90': 1.64, 'z_95':1.96, 'z_99': 2.58}
    pred_upper_ = mixture_mean + Standard_scores['z_95'] * torch.sqrt(total_recal_uncertainty)
    pred_lower_ = mixture_mean - Standard_scores['z_95'] * torch.sqrt(total_recal_uncertainty)
    pred_upper_ale = mixture_mean + Standard_scores['z_95'] * torch.sqrt(aleatoric)
    pred_lower_ale = mixture_mean - Standard_scores['z_95'] * torch.sqrt(aleatoric)
    pred_upper_epi = mixture_mean + Standard_scores['z_95'] * torch.sqrt(torch.tensor(epistemic))
    pred_lower_epi = mixture_mean - Standard_scores['z_95'] * torch.sqrt(torch.tensor(epistemic))
    # Plot 95% Prediction Interval in a subplot
    ax.plot(test_index, mixture_mean, color = 'r', alpha=0.9, label='Forecast', linewidth=5.0, ls='-')
    ax.scatter(test_index, target_test, color = 'k', alpha=0.9, label='Observed value')
    ax.fill_between(test_index, pred_lower_, pred_upper_, alpha=0.4, facecolor='navy', edgecolor='None', label='95% PI')
    ax.fill_between(test_index, pred_lower_ale, pred_upper_ale, alpha=0.5, facecolor='green', edgecolor='None', label='Aleatoric Uncertainty')
    ax.fill_between(test_index, pred_lower_epi, pred_upper_epi, alpha=0.3, color='orange', label='Epistemic Uncertainty')
    ax.set_title(f"{station_name}", size=25, fontweight='bold')
    ax.set_ylabel('Solar PV Power (W)', size=22, fontweight='bold')
    ax.set_xlabel('Date / Hour', size=25, fontweight='bold')
    ax.tick_params(axis='x', rotation=30, labelsize=15)
    ax.xaxis.label.set_fontweight('bold')
    ax.tick_params(axis='y', rotation=0, labelsize=15)
    ax.yaxis.label.set_fontweight('bold')
    ax.legend(loc="upper left", ncol=1, frameon=True, fontsize='12',
              fancybox=True, framealpha=1, shadow=True, borderpad=1)
    ax.xaxis.grid(False)  # Remove x-axis grid lines
    ax.yaxis.grid(False)
    for spine in ax.spines.values():
        spine.set_linewidth(2)
        spine.set_edgecolor('black')
    # Convert NumPy arrays to Python lists
    target_test = target_test.to_dict(orient='records')
    mixture_mean = mixture_mean.tolist()
    # Store the data in the dictionary
    station_data[station_name] = {'target_test': target_test, 'mixture_mean': mixture_mean}
# Define the names of the 15 stations
