"""#**Build The StemGNN Monte Carlo Probabilistic Model**

**It implements both StemGNN Architecture and Monte Carlo Dropout to Model Aleatoric and Epistemic Uncertainty**

###**Define Utilities**
"""

class ForecastDataset(Dataset):

    def __init__(self, X_train, y_train, sequence_length, sequential, stride=1):
        self.sequence_length = sequence_length
        self.X_train = X_train
        self.y_train = y_train
        self.stride = stride
        self.x_end_idx = self.get_x_end_idx()
        self.sequential = sequential

    def __getitem__(self, index):
        hi = self.x_end_idx[index]
        lo = hi - self.sequence_length
        x = self.X_train[lo:hi]
        y = self.y_train[hi-1]

        x = torch.from_numpy(x).type(torch.float)
        y = torch.from_numpy(y).type(torch.float)

        if not self.sequential:
            x = torch.flatten(x)

        return x, y

    def __len__(self):
        return len(self.x_end_idx)

    def get_x_end_idx(self):
        x_index_set = range(self.sequence_length, self.X_train.shape[0])
        x_end_idx = [x_index_set[j * self.stride] for j in range((len(x_index_set)) // self.stride)]
        return x_end_idx

def torch_loader(X_train, y_train, X_valid, y_valid, X_test, y_test, sequence_length, batch_size, sequential=False):

    train_set = ForecastDataset(X_train, y_train, sequence_length, sequential)
    train_loader = DataLoader(train_set, batch_size=batch_size, drop_last=False, shuffle=False, num_workers=0)

    valid_set = ForecastDataset(X_valid, y_valid, sequence_length, sequential)
    valid_loader = DataLoader(valid_set, batch_size=batch_size, drop_last=False, shuffle=False, num_workers=0)

    test_set = ForecastDataset(X_test, y_test, sequence_length, sequential)
    test_loader = DataLoader(test_set, batch_size=batch_size, drop_last=False, shuffle=False, num_workers=0)

    return train_loader, valid_loader, test_loader

def get_device():
    if torch.cuda.is_available():
        dev = "cuda:0"
        torch.cuda.manual_seed(42)
    else:
        dev="cpu"
    device = torch.device(dev)
    print('Running computation on: ', device)
    return device
def plot_training_curve(loss_history, lr_history):
    fig, axs = plt.subplots(1, 2, figsize=(14, 4))
    axs[0].plot(loss_history)
    axs[0].set_xlabel('Epochs')
    axs[0].set_ylabel("Model Loss")
    axs[1].plot(lr_history)
    axs[1].set_xlabel('Epochs')
    axs[1].set_ylabel("Learning rate")
    axs[1].ticklabel_format(axis='y', style='sci', scilimits=(0,0))
    fig.tight_layout()
    # Save the plot to a directory in Google Drive
    output_dir = '/content/gdrive/MyDrive/Solar_Power_Research_Plots'
    plt.savefig(f'{output_dir}/Training_Loss_and_Learning_Rate_History_Plot_SAM.png')
def plot_training_curve_ensemble(ensemble_loss_history, ensemble_lr_history, fig_save_name):
    ensemble_size = len(ensemble_loss_history)
    fig, axs = plt.subplots(ensemble_size, 2, figsize=(12, 3*ensemble_size))
    model_idx=0
    for model_idx, (loss_history, lr_history) in enumerate(zip(ensemble_loss_history, ensemble_lr_history)):
        axs[model_idx][0].plot(loss_history)
        axs[model_idx][0].set_xlabel('Epochs')
        axs[model_idx][0].set_ylabel("Model Loss")
        axs[model_idx][1].plot(lr_history)
        axs[model_idx][1].set_xlabel('Epochs')
        axs[model_idx][1].set_ylabel("Learning rate")
        axs[model_idx][1].ticklabel_format(axis='y', style='sci', scilimits=(0,0))
        model_idx += 1
    fig.tight_layout()
    fig.savefig(fig_save_name, bbox_inches='tight')
def plot_training_curve_bnn(nll_history, kl_history, lr_history, fig_save_name):
    fig, axs = plt.subplots(1, 3, figsize=(21, 4))
    axs[0].plot(nll_history)
    axs[0].set_xlabel('Epochs')
    axs[0].set_ylabel("NLL Loss")
    axs[1].plot(kl_history)
    axs[1].set_xlabel('Epochs')
    axs[1].set_ylabel("KLL Loss")
    axs[2].plot(lr_history)
    axs[2].set_xlabel('Epochs')
    axs[2].set_ylabel("Learning rate")
    axs[2].ticklabel_format(axis='y', style='sci', scilimits=(0,0))
    fig.tight_layout()
    fig.savefig(fig_save_name, bbox_inches='tight')
def rescale(y, stats):
    y = y * stats['df_power_std'] + stats['df_power_mean']
    y = np.exp(y)-1
    return y

