    columns = df_power_.columns.values.copy()
    if task == 'regression':
       df_power_cols = [col for col in columns if col.startswith('Power(W)_')]
       df_power = df_power_[df_power_cols].copy()
       has_nan_inf = np.any(np.isnan(df_power.values) | np.isinf(df_power.values))
       if has_nan_inf:
           print("DataFrame df_power contains NaN, inf, or other invalid values.")
       else:
           print("DataFrame df_power does not contain NaN, inf, or other invalid values.")
       df_power_mean = df_power.mean()
