"""###**Using the Best Hyperparameter Values After Optuna Optimization**

{'multi_layer': 2, 'dropout_rate': 0.5673712232274474, 'leaky_rate': 0.8858057246269018, 'learning_rate': 0.000271001758340491, 'weight_decay': 0.09673007828679685}
"""

# Set random seed
seed = 111
random.seed(seed)
np.random.seed(seed)
torch.manual_seed(seed)
class GLU(nn.Module):
    def __init__(self, input_channel, output_channel):
        super(GLU, self).__init__()
        self.linear_left = nn.Linear(input_channel, output_channel)
        self.linear_right = nn.Linear(input_channel, output_channel)
    def forward(self, x):
        return torch.mul(self.linear_left(x), torch.sigmoid(self.linear_right(x)))
class StockBlockLayer(nn.Module):
    def __init__(self, time_step, unit, multi_layer, stack_cnt=0, dropout_rate=0.5):
        super(StockBlockLayer, self).__init__()
        self.time_step = time_step
        self.unit = unit
        self.stack_cnt = stack_cnt
        self.multi = multi_layer
        self.dropout = nn.Dropout(p=dropout_rate)
        self.weight = nn.Parameter(
            torch.Tensor(1, 3 + 1, 1, self.time_step * self.multi,
                         self.multi * self.time_step))  # [K+1, 1, in_c, out_c]
        nn.init.xavier_normal_(self.weight)
        self.forecast = nn.Linear(self.time_step * self.multi, self.time_step * self.multi)
        self.forecast_result = nn.Linear(self.time_step * self.multi, self.time_step)
        if self.stack_cnt == 0:
            self.backcast = nn.Linear(self.time_step * self.multi, self.time_step)
        self.backcast_short_cut = nn.Linear(self.time_step, self.time_step)
        self.relu = nn.ReLU()
        self.GLUs = nn.ModuleList()
        self.output_channel = 4 * self.multi
        for i in range(3):
            if i == 0:
                self.GLUs.append(GLU(self.time_step * 4, self.time_step * self.output_channel))
                self.GLUs.append(GLU(self.time_step * 4, self.time_step * self.output_channel))
            elif i == 1:
                self.GLUs.append(GLU(self.time_step * self.output_channel, self.time_step * self.output_channel))
                self.GLUs.append(GLU(self.time_step * self.output_channel, self.time_step * self.output_channel))
            else:
                self.GLUs.append(GLU(self.time_step * self.output_channel, self.time_step * self.output_channel))
                self.GLUs.append(GLU(self.time_step * self.output_channel, self.time_step * self.output_channel))
    def spe_seq_cell(self, input):
        batch_size, k, input_channel, node_cnt, time_step = input.size()
        input = input.view(batch_size, -1, node_cnt, time_step)
        ffted = torch.fft.fft(input)
        real = torch.real(ffted).permute(0, 2, 1, 3).contiguous().reshape(batch_size, node_cnt, -1)
        img = torch.imag(ffted).permute(0, 2, 1, 3).contiguous().reshape(batch_size, node_cnt, -1)
        for i in range(3):
            real = self.GLUs[i * 2](real)
            real = self.dropout(real)
            img = self.GLUs[2 * i + 1](img)
            img = self.dropout(img)
        real = real.reshape(batch_size, node_cnt, 4, -1).permute(0, 2, 1, 3).contiguous()
        img = img.reshape(batch_size, node_cnt, 4, -1).permute(0, 2, 1, 3).contiguous()
        time_step_as_inner = torch.complex(real, img)
        iffted = torch.fft.ifft(time_step_as_inner)
        iffted = torch.real(iffted)
        return iffted
    def forward(self, x, mul_L):
        mul_L = mul_L.unsqueeze(1)
        x = x.unsqueeze(1)
        gfted = torch.matmul(mul_L, x)
        gconv_input = self.spe_seq_cell(gfted).unsqueeze(2)
        igfted = torch.matmul(gconv_input, self.weight)
        igfted = torch.sum(igfted, dim=1)
        forecast_source = torch.sigmoid(self.forecast(igfted).squeeze(1))
        forecast_source = self.dropout(forecast_source)
        forecast = self.forecast_result(forecast_source)
        if self.stack_cnt == 0:
            backcast_short = self.backcast_short_cut(x).squeeze(1)
            backcast_source = torch.sigmoid(self.backcast(igfted) - backcast_short)
        else:
            backcast_source = None
        return forecast, backcast_source
class StemGNN_MC():
    def __init__(self, input_dim, output_dim):
        super().__init__()
        self.input_dim = input_dim
        self.output_dim = output_dim
        self.task = task
        self.window_size= historical_sequence_length
        self.device = get_device()
        self.multi_layer= 2 #5 #3, # stack_cnt=2
        self.network=Network(units=self.input_dim, stack_cnt=2, time_step=self.window_size, multi_layer=self.multi_layer, output_length=self.output_dim , task=self.task)
        self.network.to(self.device)
        if self.task == "regression":
            self.criterion = torch.nn.GaussianNLLLoss(full=True, reduction='sum')
    # Use Combined NLL Loss, and L1 Loss Regularization loss # Use lambda_val = 0.5
    def get_loss(self, output, target):
        if self.task == "regression":
            nll_loss = self.criterion(output[0], target, output[1])
            #l1_loss = torch.mean(torch.abs(output[0]))
            # L2 Regularization Loss
            #l2_loss = torch.sum(torch.square(output[0]))
            combined_loss = nll_loss
            return combined_loss
    def get_loss_cal(self, mu, target, logvar):
        if self.task == "regression":
            nll_loss = self.criterion(mu, target, logvar)
            return nll_loss
    def apply_dropout(self, module):
        if type(module) == nn.Dropout:
            module.train()
    def train_retrain_calibrate_evaluate(self, train_loader, valid_loader, test_loader, n_epochs, batch_size, stats, n_samples, Nbatches):
        print('Training {} model'.format(type(self).__name__))
        learning_rate = 0.0002710017 #1e-4
        weight_decay = 0.0967300 #1e-3 #1e-6
        gamma = 0.999
        optimizer = torch.optim.Adam(self.network.parameters(), lr=learning_rate, weight_decay=weight_decay, betas=(0.9, 0.999))
        lr_scheduler = ExponentialLR(optimizer, gamma=gamma)
        lambda_val = 0.1
        metric = torch.nn.functional.mse_loss
        writer = SummaryWriter(comment=f"_{self}_{train_loader}")
        #self.network.train()
        train_loss_history, train_lr_history = [], []
        train_losses = []
        valid_losses = []
        batch_counter = 0
        batch_counter_valid = 0
        batch_counter_cal = 0
        best_model = None  # Store the best model
        best_loss = float('inf')  # Initialize best loss as infinity
        for epoch in range(1, n_epochs+1 ):
            self.network.train()
            epoch_train_loss = []
            mu_train = []
            targets_train = []
            logvar_train = []
            is_best = False
            for _ , (features , target) in enumerate(tqdm(train_loader)):
                features  = features.to(self.device)
                target = target.to(self.device)
                output = self.network(features)
                loss = self.get_loss(output, target)
                loss.backward()
                optimizer.step()
                optimizer.zero_grad()
                epoch_train_loss.append(loss.item())
                targets_train.append(target.detach().cpu())
                mu_train.append(output[0].detach().cpu())
                logvar_train.append(output[1].detach().cpu())
                writer.add_scalar('train/loss', loss.item(), batch_counter)
                writer.add_scalar('train/mse', metric(output[0], target), batch_counter)
                writer.add_scalar('train/var', output[1].mean(), batch_counter)
                batch_counter += 1
            train_lr_history.append(optimizer.param_groups[0]['lr'])
            lr_scheduler.step()
            train_loss_history.append(np.mean(epoch_train_loss))
            epoch_train_loss = np.mean(epoch_train_loss)
            targets_train = torch.cat(targets_train, dim=0)
            mu_train = torch.cat(mu_train, dim=0)
            logvar_train = torch.cat(logvar_train, dim=0)
            mse_train = metric(mu_train, targets_train)
            # Perform Validation
            self.network.eval()
            epoch_valid_loss = []
            mu_valid = []
            logvar_valid = []
            targets_valid = []
            with torch.no_grad():
                for _ , (features, target) in enumerate(tqdm(valid_loader)):
                    features, target = features.to(self.device), target.to(self.device)
                    output = self.network(features)
                    loss = self.get_loss(output, target)
                    epoch_valid_loss.append(loss.item())
                    targets_valid.append(target.detach().cpu())
                    mu_valid.append(output[0].detach().cpu())
                    logvar_valid.append(output[1].cpu())
                    writer.add_scalar('valid/loss', loss.item(), batch_counter_valid)
                    writer.add_scalar('valid/mse', metric(output[0], target), batch_counter_valid)
                    writer.add_scalar('valid/var', output[1].mean(), batch_counter_valid)
                    batch_counter_valid += 1
            epoch_valid_loss = np.mean(epoch_valid_loss)
            targets_valid = torch.cat(targets_valid, dim=0)
            mu_valid = torch.cat(mu_valid, dim=0)
            logvar_valid = torch.cat(logvar_valid, dim=0)
            mse_valid = metric(mu_valid, targets_valid)
            print(f"Epoch {epoch}:")
            print(f"train: loss: {epoch_train_loss:.5f}, mse: {mse_train:.5f}, var: {logvar_train.mean():.5f}")
            print(f"valid: loss: {epoch_valid_loss:.5f}, mse: {mse_valid:.5f}, var: {logvar_valid.mean():.5f}")
            # save epoch losses
            train_losses.append(epoch_train_loss)
            valid_losses.append(epoch_valid_loss)
            if valid_losses[-1] <= best_loss:
                best_loss = valid_losses[-1]
                best_model = self.network.state_dict()
        plot_training_curve(train_loss_history, train_lr_history)
        # Obtain the best model
        if best_model is not None:
            self.network.load_state_dict(best_model)
            # Perform Calibration
            print('Calibrating the {} Pretrained model for Uncertainty Quantification'.format(type(self).__name__))
            cal_model = self.network
            cal_model.eval()
            cal_model.apply(self.apply_dropout) # Apply dropout during evaluation
            if self.task =='regression':
                samples_mean, samples_var = [], []
                for _ in range(n_samples):
                    pred_mean_set, pred_var_set = [], []
                    for _, (features , _ ) in enumerate(valid_loader):
                        features = features.to(self.device)
                        pred_mean, pred_var, adj_mat = cal_model(features)
                        pred_mean_set.append(pred_mean.detach().cpu().numpy())
                        pred_var_set.append(pred_var.detach().cpu().numpy())
                    pred_mean_i, pred_var_i =  np.concatenate(pred_mean_set, axis=0), np.concatenate(pred_var_set, axis=0)
                    samples_mean.append(pred_mean_i)
                    samples_var.append(pred_var_i)
                samples_mean_val = np.array(samples_mean)
                samples_var_val = np.array(samples_var)
                samples_var_val = torch.tensor(samples_var)
                samples_mean_val = torch.tensor(samples_mean_val)  # Convert to a PyTorch tensor
                mixture_mean_val = torch.mean(samples_mean_val, dim=0)
                mixture_var = torch.mean(samples_var_val + torch.square(samples_mean_val), dim=0) - torch.square(mixture_mean_val)
                total_unc_val = mixture_var.numpy()
                std_val = np.sqrt(total_unc_val)
                target_val  = self.get_target_val(valid_loader)
            # Perform Evaluation
            print('Evaluating the {} Pretrained model for Uncertainty Quantification'.format(type(self).__name__))
            self.network.eval()
            self.network.apply(self.apply_dropout) # Apply dropout during evaluation
            if self.task =='regression':
                samples_mean, samples_var = [], []
                for _ in range(n_samples):
                    pred_mean_set, pred_var_set = [], []
                    for _, (features , _ ) in enumerate(test_loader):
                        features = features.to(self.device)
                        pred_mean, pred_var, adj_mat = self.network(features)
                        pred_mean_set.append(pred_mean.detach().cpu().numpy())
                        pred_var_set.append(pred_var.detach().cpu().numpy())
                    pred_mean_i, pred_var_i =  np.concatenate(pred_mean_set, axis=0), np.concatenate(pred_var_set, axis=0)
                    samples_mean.append(pred_mean_i)
                    samples_var.append(pred_var_i)
                samples_mean = np.array(samples_mean)
                samples_var = np.array(samples_var)
                samples_var = torch.tensor(samples_var)
                #aleatoric = torch.mean(samples_var, axis=0)
                samples_mean = torch.tensor(samples_mean)  # Convert to a PyTorch tensor
                mixture_mean = torch.mean(samples_mean, dim=0)
                #epistemic = torch.sum(torch.square(samples_mean - mixture_mean), dim=0) / (n_samples - 1)
                mixture_var = torch.mean(samples_var + torch.square(samples_mean), dim=0) - torch.square(mixture_mean)
                total_unc = mixture_var.numpy()
                std = np.sqrt(total_unc) # standard_deviation = numpy.sqrt(variance)
                target_test  = self.get_target_test(test_loader)
                return target_test, mixture_mean.numpy(), mixture_var.numpy(), samples_mean.numpy(), samples_var, total_unc, std, target_val, mixture_mean_val.numpy(), std_val, adj_mat
    def get_target_test(self, test_loader):
        target_set = []
        for _ , ( _ , target) in enumerate(test_loader):
            target_set.append(target.numpy())
        return np.concatenate(target_set, axis=0)
    def get_target_val(self, valid_loader):
        target_set_val = []
        for _ , ( _ , target) in enumerate(valid_loader):
            target_set_val.append(target.numpy())
        return np.concatenate(target_set_val, axis=0)
class Network(nn.Module):
    def __init__(self, units, stack_cnt, time_step, multi_layer,output_length, task,
                 horizon=1, dropout_rate= 0.567371, leaky_rate= 0.885805):
        super().__init__()
        self.output_length = output_length
        self.unit = units
        self.stack_cnt = stack_cnt
        self.unit = units
        self.alpha = leaky_rate
        self.time_step = time_step
        self.horizon = horizon
        self.dropout = nn.Dropout(p=dropout_rate)
        self.dropout_probability = dropout_rate
        self.task = task
        self.weight_key = nn.Parameter(torch.zeros(size=(self.unit, 1)))
        nn.init.xavier_uniform_(self.weight_key.data, gain=1.414)
        self.weight_query = nn.Parameter(torch.zeros(size=(self.unit, 1)))
        nn.init.xavier_uniform_(self.weight_query.data, gain=1.414)
        self.GRU = nn.GRU(self.time_step, self.unit) #, dropout=self.dropout_probability)
        self.GRU = nn.GRU(self.time_step, self.unit) #, dropout=self.dropout_probability)
        self.multi_layer = multi_layer
        self.stock_block = nn.ModuleList()
        self.stock_block.extend(
            [StockBlockLayer(self.time_step, self.unit, self.multi_layer, stack_cnt=i, dropout_rate=self.dropout_probability) for i in range(self.stack_cnt)])
        self.leakyrelu = nn.LeakyReLU(self.alpha)
        if self.task == 'regression':
            self.fc = nn.Sequential(
            nn.Linear(int(self.time_step*self.unit), int(self.time_step*self.unit)),
            nn.LeakyReLU(),
            nn.Dropout(self.dropout_probability),
            nn.Linear(int(self.time_step*self.unit), 2*self.output_length),
            )
            self.Softplus= nn.Softplus()
    def get_laplacian(self, graph, normalize):
        if normalize:
            D = torch.diag(torch.sum(graph, dim=-1) ** (-1 / 2))
            L = torch.eye(graph.size(0), device=graph.device, dtype=graph.dtype) - torch.mm(torch.mm(D, graph), D)
        else:
            D = torch.diag(torch.sum(graph, dim=-1))
            L = D - graph
        return L
    def cheb_polynomial(self, laplacian):
        N = laplacian.size(0)  # [N, N]
        laplacian = laplacian.unsqueeze(0)
        first_laplacian = torch.zeros([1, N, N], device=laplacian.device, dtype=torch.float)
        second_laplacian = laplacian
        third_laplacian = (2 * torch.matmul(laplacian, second_laplacian)) - first_laplacian
        forth_laplacian = 2 * torch.matmul(laplacian, third_laplacian) - second_laplacian
        multi_order_laplacian = torch.cat([first_laplacian, second_laplacian, third_laplacian, forth_laplacian], dim=0)
        return multi_order_laplacian
    def latent_correlation_layer(self, x):
        input, _ = self.GRU(x.permute(2, 0, 1).contiguous())
        input = input.permute(1, 0, 2).contiguous()
        attention = self.self_graph_attention(input)
        attention = torch.mean(attention, dim=0)
        degree = torch.sum(attention, dim=1)
        # laplacian is sym or not
        attention = 0.5 * (attention + attention.T)
        degree_l = torch.diag(degree)
        diagonal_degree_hat = torch.diag(1 / (torch.sqrt(degree) + 1e-7))
        laplacian = torch.matmul(diagonal_degree_hat,
                                 torch.matmul(degree_l - attention, diagonal_degree_hat))
        mul_L = self.cheb_polynomial(laplacian)
        return mul_L, attention
    def self_graph_attention(self, input):
        input = input.permute(0, 2, 1).contiguous()
        bat, N, fea = input.size()
        key = torch.matmul(input, self.weight_key)
        query = torch.matmul(input, self.weight_query)
        data = key.repeat(1, 1, N).view(bat, N * N, 1) + query.repeat(1, N, 1)
        data = data.squeeze(2)
        data = data.view(bat, N, -1)
        data = self.leakyrelu(data)
        attention = F.softmax(data, dim=2)
        attention = self.dropout(attention)
        return attention
    def graph_fft(self, input, eigenvectors):
        return torch.matmul(eigenvectors, input)
    def forward(self, x):
        mul_L, attention = self.latent_correlation_layer(x)
        X = x.unsqueeze(1).permute(0, 1, 3, 2).contiguous()
        result = []
        for stack_i in range(self.stack_cnt):
            forecast, X = self.stock_block[stack_i](X, mul_L)
            result.append(forecast)
        forecast = result[0] + result[1]
        forecast = forecast.view(forecast.shape[0], -1)
        forecast = self.fc(forecast)
        if self.task == 'regression':
            mean = forecast[:, :self.output_length]
            variance = self.Softplus(forecast[:, self.output_length:])+ 1e-06
            return mean, variance, mul_L

